steps.action:
curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "{
    teams(filter: {name: {eq: \"Platform\"}}) {
      nodes {
        id
        name
        cycles(order: startDate) {
          nodes {
            id
            name
            startDate
            endDate
            status
          }
        }
      }
    }
  }
}'
